// 사내 공통 발송 문안 규칙:
// 파일·링크만 던지지 않는다. (1) 무엇이 몇 건 (2) 핵심 수치 (3) 유의점 (4) 읽는 순서.
const rows = $input.all().map(i => i.json);

const tot = rows.reduce((a, d) => {
  a.flags += (d.red_flags || []).length;
  a.p0 += (d.prescriptions || []).filter(p => p.priority === 'P0').length;
  a.p1 += (d.prescriptions || []).filter(p => p.priority === 'P1').length;
  a.defects += d.prescriptions?.length ?? 0;
  return a;
}, { flags: 0, p0: 0, p1: 0, defects: 0 });

const lines = [
  `*KO-Detect 진행 보고 — ${$now.format('yyyy-MM-dd')}*`,
  '',
  `• 시설물 ${rows.length}동 · 처방 ${tot.defects}건`,
  `• 적신호 ${tot.flags}건 · P0(응급) ${tot.p0}건 · P1(긴급) ${tot.p1}건`,
  '',
  '*시설물별 현황*',
  ...rows.map(d => {
    const f = (d.red_flags || []).map(x => x.code).join(',');
    const dev = d.health_age?.deviation;
    return `  · ${d.building.name} — 법정 ${d.inspection.statutory_grade ?? '—'} / ` +
           `BHI ${d.bhi.toFixed(1)} (${d.grade})` +
           (f ? ` :warning: ${f}` : '') +
           (dev != null ? ` · 노화편차 ${dev > 0 ? '+' : ''}${dev.toFixed(1)}년` : '');
  }),
  '',
  '*유의점*',
  ...(tot.p0 ? [`  · P0 처방 ${tot.p0}건은 소견서와 무관하게 즉시 통보 대상입니다 (§9.3)`] : []),
  '  · AI 판정은 보조 참고자료이며 책임기술자 확인·서명이 필요합니다',
  '  · 상시 계측은 시뮬레이션이며 실계측기 데이터가 아닙니다',
  '',
  '*읽는 순서* 적신호 → P0 처방 → 노화편차 순으로 보십시오.',
  '자세한 기록은 저장소 `docs/DAILY_UPDATE_<yyyymmdd>.md` 에 있습니다.',
];

return [{ json: { text: lines.join('\n'), totals: tot, count: rows.length } }];
